#!/usr/bin/env bash
# One-click installer: downloads the latest VRChat Auto-Rejoin from GitHub and installs it.
#   curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/vrchat-auto-rejoin/main/get.sh | bash
#   Extra options go after "bash -s --", e.g. ... | bash -s -- --service
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
set -euo pipefail
REPO="lokinyauv-create/vrchat-auto-rejoin"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
TAG="$(curl -fsSL "https://api.github.com/repos/$REPO/releases/latest" | grep -o '"tag_name": *"[^"]*"' | cut -d'"' -f4 || true)"
REF="${TAG:+refs/tags/$TAG}"; REF="${REF:-refs/heads/main}"
echo "Downloading VRChat Auto-Rejoin ${TAG:-main}… / Завантажую VRChat авто-повернення…"
curl -fsSL "https://codeload.github.com/$REPO/tar.gz/$REF" | tar -xz -C "$T" --strip-components=1
bash "$T/install.sh" "$@"
